#!/usr/bin/env node
/**
 * Coverage Tier Validation Script
 *
 * Reads coverage/coverage-summary.json (generated by vitest --coverage)
 * and validates per-tier coverage targets defined in spec.md §7.1.
 *
 * Usage:
 *   node scripts/check-coverage-tiers.mjs           # check generated report
 *   COVERAGE_JSON=path node scripts/check-coverage-tiers.mjs  # custom path
 *
 * Exit codes:
 *   0 - All tiers pass
 *   1 - Some tiers below target
 *   2 - Coverage report not found
 */

import { readFileSync, existsSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..");

// ── Tier configuration for Nordic collection, scoring, data, and UI code ──
const TIERS = [
  {
    name: "Tier 1: Nordic collection and scoring",
    target: 95,
    metric: "statements",
    patterns: [/\/nordic\/(sources|score)\.ts$/, /\/nordic\/ingest\.ts$/, /\/nordic\/state\.ts$/],
  },
  {
    name: "Tier 2: Ingest API",
    target: 85,
    metric: "statements",
    patterns: [/\/api\/ingest\/route\.ts$/],
  },
  {
    name: "Tier 3: Feed and page adapters",
    target: 80,
    metric: "statements",
    patterns: [/\/nordic\/sources\.ts$/],
  },
  {
    name: "Tier 4: Nordic data access",
    target: 65,
    metric: "statements",
    patterns: [/\/db\/nordic\.ts$/],
  },
  {
    name: "Tier 5: Nordic UI Components",
    target: 80,
    metric: "statements",
    patterns: [/\/components\/(article|news)\/.+\.tsx$/, /\/fetch-button\.tsx$/],
  },
  {
    name: "Tier 6: External API Wrappers",
    target: 65,
    metric: "statements",
    patterns: [/\/llm\/client\.ts$/, /\/nordic\/score\.ts$/],
  },
  {
    name: "Tier 7: RSC Pages",
    target: null, // Excluded from unit test coverage
    metric: "statements",
    patterns: [/\/app\/page\.tsx$/],
  },
];

// ── Helpers ────────────────────────────────────────────────────────────

function loadCoverage(path) {
  if (!existsSync(path)) {
    console.error(`[coverage-check] Coverage report not found: ${path}`);
    console.error(`[coverage-check] Run 'pnpm exec vitest run --coverage' first.`);
    process.exit(2);
  }
  return JSON.parse(readFileSync(path, "utf-8"));
}

function metricKey(metric) {
  return metric === "statements" ? "statements" : metric;
}

/** Compute aggregate coverage for a set of files (optionally excluding some). */
function aggregateCoverage(report, files, metric) {
  if (files.length === 0) return null;

  let totalCovered = 0;
  let total = 0;

  for (const file of files) {
    const data = report[file];
    if (!data) continue;
    const key = metricKey(metric);
    totalCovered += data[key]?.covered ?? 0;
    total += data[key]?.total ?? 0;
  }

  if (total === 0) return null;
  return { pct: (totalCovered / total) * 100, covered: totalCovered, total };
}

function formatPct(value) {
  return `${value.toFixed(2)}%`;
}

// ── Main ───────────────────────────────────────────────────────────────

function main() {
  const jsonPath = process.env.COVERAGE_JSON || resolve(ROOT, "coverage/coverage-summary.json");

  const report = loadCoverage(jsonPath);

  /** All source file paths from the report. */
  const allFiles = Object.keys(report).filter((f) => f.includes("/src/"));

  let allPass = true;
  const results = [];

  for (const tier of TIERS) {
    // Match files by pattern
    const matchedFiles = allFiles.filter((f) => tier.patterns.some((p) => p.test(f)));

    if (matchedFiles.length === 0) {
      results.push({ tier: tier.name, status: "⚠️  No files matched" });
      continue;
    }

    // Tier 5 & 7: no numeric target — just report
    if (tier.target === null) {
      const agg = aggregateCoverage(report, matchedFiles, tier.metric);
      const pctStr = agg ? formatPct(agg.pct) : "N/A";
      results.push({
        tier: tier.name,
        stmts: pctStr,
        status: `ℹ️  (${matchedFiles.length} files, target: ${tier.name.includes("Tier 5") ? "Key paths" : "Excluded"})`,
        pass: true,
      });
      continue;
    }

    const agg = aggregateCoverage(report, matchedFiles, tier.metric);
    if (!agg) {
      results.push({
        tier: tier.name,
        stmts: "N/A",
        status: "⚠️  No coverage data",
      });
      continue;
    }

    // skipFailure: compute non-skipped aggregate first
    let nonSkippedAgg = null;
    if (tier.skipFailure) {
      const nonSkippedFiles = matchedFiles.filter((f) => !tier.skipFailure.some((p) => p.test(f)));
      nonSkippedAgg = aggregateCoverage(report, nonSkippedFiles, tier.metric);
    }

    // Determine primary percentage: use non-skipped if skipFailure applies
    const primaryAgg = tier.skipFailure && nonSkippedAgg ? nonSkippedAgg : agg;
    const primaryPct = primaryAgg.pct;

    let pass = primaryPct >= tier.target;
    if (!pass) allPass = false;

    // Build detail string
    let detail = `(${primaryAgg.covered}/${primaryAgg.total} ${tier.metric})`;
    if (tier.skipFailure && nonSkippedAgg && primaryAgg !== agg) {
      // Show both: primary (excluded) first, overall as reference
      detail = `excl. skipped: ${formatPct(nonSkippedAgg.pct)} (${nonSkippedAgg.covered}/${nonSkippedAgg.total} ${tier.metric}) → overall: ${formatPct(agg.pct)} (${agg.covered}/${agg.total} ${tier.metric})`;
    }

    results.push({
      tier: tier.name,
      stmts: formatPct(primaryPct),
      target: `${tier.target}%`,
      status: pass ? "✅ PASS" : "❌ FAIL",
      pass,
      detail,
    });
  }

  // ── Output ────────────────────────────────────────────────────────────
  console.log("");
  console.log("📊 Coverage Tier Validation");
  console.log("=".repeat(60));

  for (const r of results) {
    const line = [
      r.tier.padEnd(35),
      (r.stmts || "").padStart(8),
      r.target ? `  target: ${r.target}`.padEnd(12) : " ".padEnd(12),
      r.status || "",
      r.detail || "",
    ].join("");
    console.log(line);
  }

  console.log("=".repeat(60));

  // ── Summary ───────────────────────────────────────────────────────────
  if (allPass) {
    console.log("✅ All tiers meet coverage targets.\n");
    process.exit(0);
  } else {
    console.log("❌ Some tiers are below coverage targets.\n");
    process.exit(1);
  }
}

main();
